// Obtiene todas las comidas que llegaron desde el nodo anterior.
const comidas = $input.all();


// Inicializamos los acumuladores del día.
let total_calorias = 0;
let total_proteinas = 0;
let total_carbohidratos = 0;
let total_grasas = 0;


// Array donde guardaremos el resumen individual de cada comida.
const detalle_comidas = [];


// Recorremos todas las comidas recibidas.
for (const comida of comidas) {

  // Accedemos a los campos del registro de Airtable.
  const fields = comida.json.fields || {};


  // Convertimos los valores nutricionales a números.
  // Si algún valor no existe, usamos 0.
  const calorias = Number(fields.total_calorias || 0);
  const proteinas = Number(fields.total_proteinas || 0);
  const carbohidratos = Number(fields.total_carbohidratos || 0);
  const grasas = Number(fields.total_grasas || 0);


  // Sumamos esta comida al total acumulado del día.
  total_calorias += calorias;
  total_proteinas += proteinas;
  total_carbohidratos += carbohidratos;
  total_grasas += grasas;


  // Guardamos también los datos individuales de la comida.
  detalle_comidas.push({
    descripcion: fields.descripcion_comida || 'Comida sin descripción',
    calorias: Math.round(calorias),
    proteinas: Number(proteinas.toFixed(1)),
    carbohidratos: Number(carbohidratos.toFixed(1)),
    grasas: Number(grasas.toFixed(1))
  });
}


// Devolvemos un único item.
// Contiene tanto las comidas individuales como los totales del día.
return [
  {
    json: {

      // Detalle individual de las comidas.
      detalle_comidas,

      // Totales acumulados del día.
      total_calorias: Math.round(total_calorias),
      total_proteinas: Number(total_proteinas.toFixed(1)),
      total_carbohidratos: Number(total_carbohidratos.toFixed(1)),
      total_grasas: Number(total_grasas.toFixed(1)),

      // Cantidad de comidas encontradas.
      cantidad_comidas: comidas.length
    }
  }
];

// Obtiene todas las comidas del usuario que llegaron desde el nodo anterior.
const comidas = $input.all();


// Ordenamos las comidas desde la más reciente a la más antigua.
// Usamos createdTime porque incluye fecha y hora exacta de creación.
comidas.sort((a, b) => {
  return new Date(b.json.createdTime) - new Date(a.json.createdTime);
});


// Nos quedamos únicamente con las últimas 5 comidas registradas.
const ultimasCinco = comidas.slice(0, 5);


// Preparamos una versión simplificada de cada comida
// para que luego sea fácil mostrarla en Telegram.
const historial = ultimasCinco.map(comida => {
  const fields = comida.json.fields || {};

  return {
    fecha: fields.fecha_comida || '',
    descripcion: fields.descripcion_comida || 'Comida sin descripción',
    calorias: Math.round(Number(fields.total_calorias || 0)),
    proteinas: Number(Number(fields.total_proteinas || 0).toFixed(1)),
    carbohidratos: Number(Number(fields.total_carbohidratos || 0).toFixed(1)),
    grasas: Number(Number(fields.total_grasas || 0).toFixed(1))
  };
});


// Devolvemos un solo item con el historial preparado.
return [
  {
    json: {
      historial,
      cantidad: historial.length
    }
  }
];

