// Obtiene todas las comidas del usuario encontradas hoy.
const comidas = $input.all();

// Inicializamos acumuladores.
let total_calorias = 0;
let total_proteinas = 0;
let total_carbohidratos = 0;
let total_grasas = 0;

// Recorremos las comidas y sumamos sus valores nutricionales.
for (const comida of comidas) {
  const fields = comida.json.fields || {};

  total_calorias += Number(fields.total_calorias || 0);
  total_proteinas += Number(fields.total_proteinas || 0);
  total_carbohidratos += Number(fields.total_carbohidratos || 0);
  total_grasas += Number(fields.total_grasas || 0);
}

// Devuelve un solo item con el consumo acumulado de hoy.
return [
  {
    json: {
      total_calorias: Math.round(total_calorias),
      total_proteinas: Number(total_proteinas.toFixed(1)),
      total_carbohidratos: Number(total_carbohidratos.toFixed(1)),
      total_grasas: Number(total_grasas.toFixed(1))
    }
  }
];

