(() => {
  // Recupera la última interpretación realizada por "Normalizar comida".
  const salida = $('Normalizar comida').last().json.output;

  // Asegura que siempre trabajemos con un array.
  const alimentos = Array.isArray(salida)
    ? salida
    : salida
      ? [salida]
      : [];

  // Arma el detalle de lo que NutriAI interpretó.
  const detalle = alimentos
    .map(item =>
      '• ' + (item.nombre ?? 'alimento') +
      ' — ' +
      (item.cantidad ?? 'cantidad faltante') +
      ' ' +
      (item.unidad ?? 'unidad faltante')
    )
    .join('\n');

  return (
    '✏️ Corregí los datos de la comida.\n\n' +
    'Interpreté tu comida así:\n' +
    detalle +
    '\n\nEscribime nuevamente la comida con las cantidades correctas.\n\n' +
    'Por ejemplo:\n' +
    '🍌 1 banana y 1 pera\n' +
    '🍗 200 g de pollo con 150 g de arroz'
  );
})()
}}

